/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["cpp"]=g.BC_LEI_REVISAO["cpp"]||{};g.BC_LEI_REVISAO["cpp"][16]=[{"key":"cpp:78","law":"cpp","ref":"78","label":"CPP — art. 78","paragraphs":["Art. 78. Na determinação da competência por conexão ou continência, serão observadas as seguintes regras: (“Caput” do artigo com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","I - no concurso entre a competência do júri e a de outro órgão da jurisdição comum, prevalecerá a competência do júri, salvo os casos de homicídios cometidos por membros de organizações criminosas ultraviolentas, grupo paramilitar ou milícia privada, ou sua tentativa, na forma do art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil; (Inciso com redação dada pela Lei nº 15.358, de 24/3/2026)","II - no concurso de jurisdições da mesma categoria:","a) preponderará a do lugar da infração, à qual for cominada a pena mais grave;","b) prevalecerá a do lugar em que houver ocorrido o maior número de infrações, se as respectivas penas forem de igual gravidade;","c) firmar-se-á a competência pela prevenção, nos outros casos; (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","III - no concurso de jurisdições de diversas categorias, predominará a de maior graduação; (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","IV - no concurso entre a jurisdição comum e a especial, prevalecerá esta. (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cf:5","law":"cf","ref":"5","label":"Constituição Federal — art. 5","paragraphs":["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","I - homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição;","II - ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei;","III - ninguém será submetido a tortura nem a tratamento desumano ou degradante;","IV - é livre a manifestação do pensamento, sendo vedado o anonimato;","V - é assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou à imagem;","VI - é inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias;","VII - é assegurada, nos termos da lei, a prestação de assistência religiosa nas entidades civis e militares de internação coletiva;","VIII - ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e recusar-se a cumprir prestação alternativa, fixada em lei;","IX - é livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de censura ou licença;","X - são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação;","XI - a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial;","XII - é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;","XIII - é livre o exercício de qualquer trabalho, ofício ou profissão, atendidas as qualificações profissionais que a lei estabelecer;","XIV - é assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional;","XV - é livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus bens;","XVI - todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;","XVII - é plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar;","XVIII - a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento;","XIX - as associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado;","XX - ninguém poderá ser compelido a associar-se ou a permanecer associado;","XXI - as entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados judicial ou extrajudicialmente;","XXII - é garantido o direito de propriedade;","XXIII - a propriedade atenderá a sua função social;","XXIV - a lei estabelecerá o procedimento para desapropriação por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos nesta Constituição;","XXV - no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano;","XXVI - a pequena propriedade rural, assim definida em lei, desde que trabalhada pela família, não será objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, dispondo a lei sobre os meios de financiar o seu desenvolvimento;","XXVII - aos autores pertence o direito exclusivo de utilização, publicação ou reprodução de suas obras, transmissível aos herdeiros pelo tempo que a lei fixar;","XXVIII - são assegurados, nos termos da lei:","a) a proteção às participações individuais em obras coletivas e à reprodução da imagem e voz humanas, inclusive nas atividades desportivas;","b) o direito de fiscalização do aproveitamento econômico das obras que criarem ou de que participarem aos criadores, aos intérpretes e às respectivas representações sindicais e associativas;","XXIX - a lei assegurará aos autores de inventos industriais privilégio temporário para sua utilização, bem como proteção às criações industriais, à propriedade das marcas, aos nomes de empresas e a outros signos distintivos, tendo em vista o interesse social e o desenvolvimento tecnológico e econômico do País;","XXX - é garantido o direito de herança;","XXXI - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do de cujus;","XXXII - o Estado promoverá, na forma da lei, a defesa do consumidor;","XXXIII - todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, que serão prestadas no prazo da lei, sob pena de responsabilidade, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado;","XXXIV - são a todos assegurados, independentemente do pagamento de taxas:","a) o direito de petição aos poderes públicos em defesa de direitos ou contra ilegalidade ou abuso de poder;","b) a obtenção de certidões em repartições públicas, para defesa de direitos e esclarecimento de situações de interesse pessoal;","XXXV - a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;","XXXVI - a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;","XXXVII - não haverá juízo ou tribunal de exceção;","XXXVIII - é reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados:","a) a plenitude de defesa;","b) o sigilo das votações;","c) a soberania dos veredictos;","d) a competência para o julgamento dos crimes dolosos contra a vida;","XXXIX - não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal;","XL - a lei penal não retroagirá, salvo para beneficiar o réu;","XLI - a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;","XLII - a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;","XLIII - a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem;","XLIV - constitui crime inafiançável e imprescritível a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado democrático;","XLV - nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser, nos termos da lei, estendidas aos sucessores e contra eles executadas, até o limite do valor do patrimônio transferido;","XLVI - a lei regulará a individualização da pena e adotará, entre outras, as seguintes:","a) privação ou restrição da liberdade;","b) perda de bens;","c) multa;","d) prestação social alternativa;","e) suspensão ou interdição de direitos;","XLVII - não haverá penas:","a) de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX;","b) de caráter perpétuo;","c) de trabalhos forçados;","d) de banimento;","e) cruéis;","XLVIII - a pena será cumprida em estabelecimentos distintos, de acordo com a natureza do delito, a idade e o sexo do apenado;","XLIX - é assegurado aos presos o respeito à integridade física e moral;","L - às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação;","LI - nenhum brasileiro será extraditado, salvo o naturalizado, em caso de crime comum, praticado antes da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei;","LII - não será concedida extradição de estrangeiro por crime político ou de opinião;","LIII - ninguém será processado nem sentenciado senão pela autoridade competente;","LIV - ninguém será privado da liberdade ou de seus bens sem o devido processo legal;","LV - aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e a ampla defesa, com os meios e recursos a ela inerentes;","LVI - são inadmissíveis, no processo, as provas obtidas por meios ilícitos;","LVII - ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;","LVIII - o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei;","LIX - será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal;","LX - a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem;","LXI - ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;","LXII - a prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada;","LXIII - o preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado;","LXIV - o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial;","LXV - a prisão ilegal será imediatamente relaxada pela autoridade judiciária;","LXVI - ninguém será levado à prisão ou nela mantido quando a lei admitir a liberdade provisória, com ou sem fiança;","LXVII - não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;","LXVIII - conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder;","LXIX - conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública ou agente de pessoa jurídica no exercício de atribuições do poder público;","LXX - o mandado de segurança coletivo pode ser impetrado por:","a) partido político com representação no Congresso Nacional;","b) organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados;","LXXI - conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania;","LXXII - conceder-se-á habeas data:","a) para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público;","b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo;","LXXIII - qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, salvo comprovada má-fé, isento de custas judiciais e do ônus da sucumbência;","LXXIV - o Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos;","LXXV - o Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na sentença;","LXXVI - são gratuitos para os reconhecidamente pobres, na forma da lei:","a) o registro civil de nascimento;","b) a certidão de óbito;","LXXVII - são gratuitas as ações de habeas corpus e habeas data, e, na forma da lei, os atos necessários ao exercício da cidadania.","LXXVIII - a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação. (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","LXXIX - é assegurado, nos termos da lei, o direito à proteção dos dados pessoais, inclusive nos meios digitais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","§ 1º As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.","§ 2º Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte.","§ 3º Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)","§ 4º O Brasil se submete à jurisdição de Tribunal Penal Internacional a cuja criação tenha manifestado adesão. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html"},{"key":"cpp:74","law":"cpp","ref":"74","label":"CPP — art. 74","paragraphs":["Art. 74. A competência pela natureza da infração será regulada pelas leis de organização judiciária, salvo a competência privativa do Tribunal do Júri.","§ 1º Compete ao Tribunal do Júri o julgamento dos crimes previstos nos arts. 121, §§ 1º e 2º, 122, parágrafo único, 123, 124, 125, 126 e 127 do Código Penal, consumados ou tentados. (Parágrafo com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 2º Se, iniciado o processo perante um juiz, houver desclassificação para infração da competência de outro, a este será remetido o processo, salvo se mais graduada for a jurisdição do primeiro, que, em tal caso, terá sua competência prorrogada.","§ 3º Se o juiz da pronúncia desclassificar a infração para outra atribuída à competência de juiz singular, observar-se-á o disposto no art. 410; mas, se a desclassificação for feita pelo próprio Tribunal do Júri, a seu presidente caberá proferir a sentença (art. 492, § 2º)."],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cp:121-A","law":"cp","ref":"121-A","label":"Código Penal — art. 121-A","paragraphs":["Art. 121-A. Matar mulher por razões da condição do sexo feminino: (“Caput” do artigo acrescido pela Lei nº 14.994, de 9/10/2024)","Pena - reclusão, de 20 (vinte) a 40 (quarenta) anos. (Pena acrescida pela Lei nº 14.994, de 9/10/2024)","§ 1º Considera-se que há razões da condição do sexo feminino quando o crime envolve:","I - violência doméstica e familiar;","II - menosprezo ou discriminação à condição de mulher. (Parágrafo acrescido pela Lei nº 14.994, de 9/10/2024)","§ 2º A pena do feminicídio é aumentada de 1/3 (um terço) até a metade se o crime é praticado:","I - durante a gestação, nos 3 (três) meses posteriores ao parto ou se a vítima é a mãe ou a responsável por criança, adolescente ou pessoa com deficiência de qualquer idade;","II - contra pessoa menor de 14 (catorze) anos, maior de 60 (sessenta) anos, com deficiência ou portadora de doenças degenerativas que acarretem condição limitante ou de vulnerabilidade física ou mental;","III - na presença física ou virtual de descendente ou de ascendente da vítima;","IV - em descumprimento das medidas protetivas de urgência previstas nos incisos I, II e III do caput do art. 22 da Lei nº 11.340, de 7 de agosto de 2006 (Lei Maria da Penha);","V - nas circunstâncias previstas nos incisos III, IV e VIII do § 2º do art. 121 deste Código. (Parágrafo acrescido pela Lei nº 14.994, de 9/10/2024)","Coautoria (Nome jurídico acrescido pela Lei nº 14.994, de 9/10/2024)","§ 3º Comunicam-se ao coautor ou partícipe as circunstâncias pessoais elementares do crime previstas no § 1º deste artigo. (Parágrafo acrescido pela Lei nº 14.994, de 9/10/2024)","Vicaricídio (Nome jurídico acrescido pela Lei nº 15.384, de 9/4/2026)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html"},{"key":"cpp:413","law":"cpp","ref":"413","label":"CPP — art. 413","paragraphs":["Art. 413. O juiz, fundamentadamente, pronunciará o acusado, se convencido da materialidade do fato e da existência de indícios suficientes de autoria ou de participação. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º A fundamentação da pronúncia limitar-se-á à indicação da materialidade do fato e da existência de indícios suficientes de autoria ou de participação, devendo o juiz declarar o dispositivo legal em que julgar incurso o acusado e especificar as circunstâncias qualificadoras e as causas de aumento de pena. (Parágrafo único transformado em § 1º e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Se o crime for afiançável, o juiz arbitrará o valor da fiança para a concessão ou manutenção da liberdade provisória. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º O juiz decidirá, motivadamente, no caso de manutenção, revogação ou substituição da prisão ou medida restritiva de liberdade anteriormente decretada e, tratando-se de acusado solto, sobre a necessidade da decretação da prisão ou imposição de quaisquer das medidas previstas no Título IX do Livro I deste Código. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:414","law":"cpp","ref":"414","label":"CPP — art. 414","paragraphs":["Art. 414. Não se convencendo da materialidade do fato ou da existência de indícios suficientes de autoria ou de participação, o juiz, fundamentadamente, impronunciará o acusado. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Enquanto não ocorrer a extinção da punibilidade, poderá ser formulada nova denúncia ou queixa se houver prova nova. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:415","law":"cpp","ref":"415","label":"CPP — art. 415","paragraphs":["Art. 415. O juiz, fundamentadamente, absolverá desde logo o acusado, quando: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - provada a inexistência do fato; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - provado não ser ele autor ou partícipe do fato; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","III - o fato não constituir infração penal; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","IV - demonstrada causa de isenção de pena ou de exclusão do crime. (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Não se aplica o disposto no inciso IV do caput deste artigo ao caso de inimputabilidade prevista no caput do art. 26 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal, salvo quando esta for a única tese defensiva. (Primitivo § 1º transformado em parágrafo único e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:419","law":"cpp","ref":"419","label":"CPP — art. 419","paragraphs":["Art. 419. Quando o juiz se convencer, em discordância com a acusação, da existência de crime diverso dos referidos no § 1º do art. 74 deste Código e não for competente para o julgamento, remeterá os autos ao juiz que o seja. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Remetidos os autos do processo a outro juiz, à disposição deste ficará o acusado preso. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:406","law":"cpp","ref":"406","label":"CPP — art. 406","paragraphs":["Art. 406. O juiz, ao receber a denúncia ou a queixa, ordenará a citação do acusado para responder a acusação, por escrito, no prazo de 10 (dez) dias. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º O prazo previsto no caput deste artigo será contado a partir do efetivo cumprimento do mandado ou do comparecimento, em juízo, do acusado ou de defensor constituído, no caso de citação inválida ou por edital. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º A acusação deverá arrolar testemunhas, até o máximo de 8 (oito), na denúncia ou na queixa. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Na resposta, o acusado poderá argüir preliminares e alegar tudo que interesse a sua defesa, oferecer documentos e justificações, especificar as provas pretendidas e arrolar testemunhas, até o máximo de 8 (oito), qualificando-as e requerendo sua intimação, quando necessário. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:422","law":"cpp","ref":"422","label":"CPP — art. 422","paragraphs":["Art. 422. Ao receber os autos, o presidente do Tribunal do Júri determinará a intimação do órgão do Ministério Público ou do querelante, no caso de queixa, e do defensor, para, no prazo de 5 (cinco) dias, apresentarem rol de testemunhas que irão depor em plenário, até o máximo de 5 (cinco), oportunidade em que poderão juntar documentos e requerer diligência. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:411","law":"cpp","ref":"411","label":"CPP — art. 411","paragraphs":["Art. 411. Na audiência de instrução, proceder-se-á à tomada de declarações do ofendido, se possível, à inquirição das testemunhas arroladas pela acusação e pela defesa, nesta ordem, bem como aos esclarecimentos dos peritos, às acareações e ao reconhecimento de pessoas e coisas, interrogando-se, em seguida, o acusado e procedendo-se o debate. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Os esclarecimentos dos peritos dependerão de prévio requerimento e de deferimento pelo juiz. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º As provas serão produzidas em uma só audiência, podendo o juiz indeferir as consideradas irrelevantes, impertinentes ou protelatórias. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Encerrada a instrução probatória, observar-se-á, se for o caso, o disposto no art. 384 deste Código. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 4º As alegações serão orais, concedendo-se a palavra, respectivamente, à acusação e à defesa, pelo prazo de 20 (vinte) minutos, prorrogáveis por mais 10 (dez). (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 5º Havendo mais de 1 (um) acusado, o tempo previsto para a acusação e a defesa de cada um deles será individual. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 6º Ao assistente do Ministério Público, após a manifestação deste, serão concedidos 10 (dez) minutos, prorrogando-se por igual período o tempo de manifestação da defesa. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 7º Nenhum ato será adiado, salvo quando imprescindível à prova faltante, determinando o juiz a condução coercitiva de quem deva comparecer. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 8º A testemunha que comparecer será inquirida, independentemente da suspensão da audiência, observada em qualquer caso a ordem estabelecida no caput deste artigo. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 9º Encerrados os debates, o juiz proferirá a sua decisão, ou o fará em 10 (dez) dias, ordenando que os autos para isso lhe sejam conclusos. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:407","law":"cpp","ref":"407","label":"CPP — art. 407","paragraphs":["Art. 407. As exceções serão processadas em apartado, nos termos dos arts. 95 a 112 deste Código. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:408","law":"cpp","ref":"408","label":"CPP — art. 408","paragraphs":["Art. 408. Não apresentada a resposta no prazo legal, o juiz nomeará defensor para oferecê-la em até 10 (dez) dias, concedendo-lhe vista dos autos. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:409","law":"cpp","ref":"409","label":"CPP — art. 409","paragraphs":["Art. 409. Apresentada a defesa, o juiz ouvirá o Ministério Público ou o querelante sobre preliminares e documentos, em 5 (cinco) dias. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:410","law":"cpp","ref":"410","label":"CPP — art. 410","paragraphs":["Art. 410. O juiz determinará a inquirição das testemunhas e a realização das diligências requeridas pelas partes, no prazo máximo de 10 (dez) dias. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:412","law":"cpp","ref":"412","label":"CPP — art. 412","paragraphs":["Art. 412. O procedimento será concluído no prazo máximo de 90 (noventa) dias. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cp:26","law":"cp","ref":"26","label":"Código Penal — art. 26","paragraphs":["Art. 26. É isento de pena o agente que, por doença mental ou desenvolvimento mental incompleto ou retardado, era, ao tempo da ação ou da omissão, inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento.","Redução de pena","Parágrafo único. A pena pode ser reduzida de um a dois terços, se o agente, em virtude de perturbação de saúde mental ou por desenvolvimento mental incompleto ou retardado não era inteiramente capaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento. (Artigo com redação dada pela Lei nº 7.209, de 11/7/1984)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html"},{"key":"cpp:397","law":"cpp","ref":"397","label":"CPP — art. 397","paragraphs":["Art. 397. Após o cumprimento do disposto no art. 396-A, e parágrafos, deste Código, o juiz deverá absolver sumariamente o acusado quando verificar: (“Caput” do artigo com redação dada pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)","I - a existência manifesta de causa excludente da ilicitude do fato; (Inciso acrescido pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)","II - a existência manifesta de causa excludente da culpabilidade do agente, salvo inimputabilidade; (Inciso acrescido pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)","III - que o fato narrado evidentemente não constitui crime; ou (Inciso acrescido pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)","IV - extinta a punibilidade do agente. (Inciso acrescido pela Lei nº 11.719, de 20/6/2008, publicada no DOU de 23/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:418","law":"cpp","ref":"418","label":"CPP — art. 418","paragraphs":["Art. 418. O juiz poderá dar ao fato definição jurídica diversa da constante da acusação, embora o acusado fique sujeito a pena mais grave. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:581","law":"cpp","ref":"581","label":"CPP — art. 581","paragraphs":["Art. 581. Caberá recurso, no sentido estrito, da decisão, despacho ou sentença:","I - que não receber a denúncia ou a queixa;","II - que concluir pela incompetência do juízo;","III - que julgar procedentes as exceções, salvo a de suspeição;","IV - que pronunciar o réu; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","V - que conceder, negar, arbitrar, cassar ou julgar inidônea a fiança, indeferir requerimento de prisão preventiva ou revogá-la, conceder liberdade provisória ou relaxar a prisão em flagrante; (Inciso com redação dada pela Lei nº 7.780, de 22/6/1989)","VI - (Revogado pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VII - que julgar quebrada a fiança ou perdido o seu valor;","VIII - que decretar a prescrição ou julgar, por outro modo, extinta a punibilidade;","IX - que indeferir o pedido de reconhecimento da prescrição ou de outra causa extintiva da punibilidade;","X - que conceder ou negar a ordem de habeas corpus;","XI - que conceder, negar ou revogar a suspensão condicional da pena;","XII - que conceder, negar ou revogar livramento condicional;","XIII - que anular o processo da instrução criminal, no todo ou em parte;","XIV - que incluir jurado na lista geral ou desta o excluir;","XV - que denegar a apelação ou a julgar deserta;","XVI - que ordenar a suspensão do processo, em virtude de questão prejudicial;","XVII - que decidir sobre a unificação de penas;","XVIII - que decidir o incidente de falsidade;","XIX - que decretar medida de segurança, depois de transitar a sentença em julgado;","XX - que impuser medida de segurança por transgressão de outra;","XXI - que mantiver ou substituir a medida de segurança, nos casos do art. 774;","XXII - que revogar a medida de segurança;","XXIII - que deixar de revogar a medida de segurança, nos casos em que a lei admita a revogação;","XXIV - que converter a multa em detenção ou em prisão simples;","XXV - que recusar homologação à proposta de acordo de não persecução penal, previsto no art. 28-A desta Lei. (Inciso acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:416","law":"cpp","ref":"416","label":"CPP — art. 416","paragraphs":["Art. 416. Contra a sentença de impronúncia ou de absolvição sumária caberá apelação. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:421","law":"cpp","ref":"421","label":"CPP — art. 421","paragraphs":["Art. 421. Preclusa a decisão de pronúncia, os autos serão encaminhados ao juiz presidente do Tribunal do Júri. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Ainda que preclusa a decisão de pronúncia, havendo circunstância superveniente que altere a classificação do crime, o juiz ordenará a remessa dos autos ao Ministério Público. (Parágrafo único transformado em § 1º e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Em seguida, os autos serão conclusos ao juiz para decisão. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:423","law":"cpp","ref":"423","label":"CPP — art. 423","paragraphs":["Art. 423. Deliberando sobre os requerimentos de provas a serem produzidas ou exibidas no plenário do júri, e adotadas as providências devidas, o juiz presidente: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - ordenará as diligências necessárias para sanar qualquer nulidade ou esclarecer fato que interesse ao julgamento da causa; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - fará relatório sucinto do processo, determinando sua inclusão em pauta da reunião do Tribunal do Júri. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:427","law":"cpp","ref":"427","label":"CPP — art. 427","paragraphs":["Art. 427. Se o interesse da ordem pública o reclamar ou houver dúvida sobre a imparcialidade do júri ou a segurança pessoal do acusado, o Tribunal, a requerimento do Ministério Público, do assistente, do querelante ou do acusado ou mediante representação do juiz competente, poderá determinar o desaforamento do julgamento para outra comarca da mesma região, onde não existam aqueles motivos, preferindo-se as mais próximas.","(“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º O pedido de desaforamento será distribuído imediatamente e terá preferência de julgamento na Câmara ou Turma competente. (Parágrafo único transformado em § 1º e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Sendo relevantes os motivos alegados, o relator poderá determinar, fundamentadamente, a suspensão do julgamento pelo júri. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Será ouvido o juiz presidente, quando a medida não tiver sido por ele solicitada. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 4º Na pendência de recurso contra a decisão de pronúncia ou quando efetivado o julgamento, não se admitirá o pedido de desaforamento, salvo, nesta última hipótese, quanto a fato ocorrido durante ou após a realização de julgamento anulado. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:428","law":"cpp","ref":"428","label":"CPP — art. 428","paragraphs":["Art. 428. O desaforamento também poderá ser determinado, em razão do comprovado excesso de serviço, ouvidos o juiz presidente e a parte contrária, se o julgamento não puder ser realizado no prazo de 6 (seis) meses, contado do trânsito em julgado da decisão de pronúncia. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Para a contagem do prazo referido neste artigo, não se computará o tempo de adiamentos, diligências ou incidentes de interesse da defesa. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Não havendo excesso de serviço ou existência de processos aguardando julgamento em quantidade que ultrapasse a possibilidade de apreciação pelo Tribunal do Júri, nas reuniões periódicas previstas para o exercício, o acusado poderá requerer ao Tribunal que determine a imediata realização do julgamento. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:468","law":"cpp","ref":"468","label":"CPP — art. 468","paragraphs":["Art. 468. À medida que as cédulas forem sendo retiradas da urna, o juiz presidente as lerá, e a defesa e, depois dela, o Ministério Público poderão recusar os jurados sorteados, até 3 (três) cada parte, sem motivar a recusa. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. O jurado recusado imotivadamente por qualquer das partes será excluído daquela sessão de instrução e julgamento, prosseguindo-se o sorteio para a composição do Conselho de Sentença com os jurados remanescentes. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:466","law":"cpp","ref":"466","label":"CPP — art. 466","paragraphs":["Art. 466. Antes do sorteio dos membros do Conselho de Sentença, o juiz presidente esclarecerá sobre os impedimentos, a suspeição e as incompatibilidades constantes dos arts. 448 e 449 deste Código. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º O juiz presidente também advertirá os jurados de que, uma vez sorteados, não poderão comunicar-se entre si e com outrem, nem manifestar sua opinião sobre o processo, sob pena de exclusão do Conselho e multa, na forma do § 2º do art. 436 deste Código. (Parágrafo acrescido pela Lei nº 263, de 23/2/1948, e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º A incomunicabilidade será certificada nos autos pelo oficial de justiça. (Primitivo parágrafo único transformado em § 2º pela Lei nº 263, de 23/2/1948, e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:472","law":"cpp","ref":"472","label":"CPP — art. 472","paragraphs":["Art. 472. Formado o Conselho de Sentença, o presidente, levantando-se, e, com ele, todos os presentes, fará aos jurados a seguinte exortação:","Em nome da lei, concito-vos a examinar esta causa com imparcialidade e a proferir a vossa decisão de acordo com a vossa consciência e os ditames da justiça.","Os jurados, nominalmente chamados pelo presidente, responderão:","Assim o prometo. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. O jurado, em seguida, receberá cópias da pronúncia ou, se for o caso, das decisões posteriores que julgaram admissível a acusação e do relatório do processo. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:473","law":"cpp","ref":"473","label":"CPP — art. 473","paragraphs":["Art. 473. Prestado o compromisso pelos jurados, será iniciada a instrução plenária quando o juiz presidente, o Ministério Público, o assistente, o querelante e o defensor do acusado tomarão, sucessiva e diretamente, as declarações do ofendido, se possível, e inquirirão as testemunhas arroladas pela acusação. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Para a inquirição das testemunhas arroladas pela defesa, o defensor do acusado formulará as perguntas antes do Ministério Público e do assistente, mantidos no mais a ordem e os critérios estabelecidos neste artigo. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Os jurados poderão formular perguntas ao ofendido e às testemunhas, por intermédio do juiz presidente. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º As partes e os jurados poderão requerer acareações, reconhecimento de pessoas e coisas e esclarecimento dos peritos, bem como a leitura de peças que se refiram, exclusivamente, às provas colhidas por carta precatória e às provas cautelares, antecipadas ou não repetíveis. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:474","law":"cpp","ref":"474","label":"CPP — art. 474","paragraphs":["Art. 474. A seguir será o acusado interrogado, se estiver presente, na forma estabelecida no Capítulo III do Título VII do Livro I deste Código, com as alterações introduzidas nesta Seção. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º O Ministério Público, o assistente, o querelante e o defensor, nessa ordem, poderão formular, diretamente, perguntas ao acusado. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Os jurados formularão perguntas por intermédio do juiz presidente. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Não se permitirá o uso de algemas no acusado durante o período em que permanecer no plenário do júri, salvo se absolutamente necessário à ordem dos trabalhos, à segurança das testemunhas ou à garantia da integridade física dos presentes. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:474-A","law":"cpp","ref":"474-A","label":"CPP — art. 474-A","paragraphs":["Art. 474-A. Durante a instrução em plenário, todas as partes e demais sujeitos processuais presentes no ato deverão respeitar a dignidade da vítima, sob pena de responsabilização civil, penal e administrativa, cabendo ao juiz presidente garantir o cumprimento do disposto neste artigo, vedadas:","I - a manifestação sobre circunstâncias ou elementos alheios aos fatos objeto de apuração nos autos;","II - a utilização de linguagem, de informações ou de material que ofendam a dignidade da vítima ou de testemunhas. (Artigo acrescido pela Lei nº 14.245, de 22/11/2021)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:477","law":"cpp","ref":"477","label":"CPP — art. 477","paragraphs":["Art. 477. O tempo destinado à acusação e à defesa será de uma hora e meia para cada, e de uma hora para a réplica e outro tanto para a tréplica. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Havendo mais de um acusador ou mais de um defensor, combinarão entre si a distribuição do tempo, que, na falta de acordo, será dividido pelo juiz presidente, de forma a não exceder o determinado neste artigo. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Havendo mais de 1 (um) acusado, o tempo para a acusação e a defesa será acrescido de 1 (uma) hora e elevado ao dobro o da réplica e da tréplica, observado o disposto no § 1º deste artigo. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:478","law":"cpp","ref":"478","label":"CPP — art. 478","paragraphs":["Art. 478. Durante os debates as partes não poderão, sob pena de nulidade, fazer referências: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - à decisão de pronúncia, às decisões posteriores que julgaram admissível a acusação ou à determinação do uso de algemas como argumento de autoridade que beneficiem ou prejudiquem o acusado; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - ao silêncio do acusado ou à ausência de interrogatório por falta de requerimento, em seu prejuízo. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:479","law":"cpp","ref":"479","label":"CPP — art. 479","paragraphs":["Art. 479. Durante o julgamento não será permitida a leitura de documento ou a exibição de objeto que não tiver sido juntado aos autos com a antecedência mínima de 3 (três) dias úteis, dando-se ciência à outra parte. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Compreende-se na proibição deste artigo a leitura de jornais ou qualquer outro escrito, bem como a exibição de vídeos, gravações, fotografias, laudos, quadros, croqui ou qualquer outro meio assemelhado, cujo conteúdo versar sobre a matéria de fato submetida à apreciação e julgamento dos jurados. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:482","law":"cpp","ref":"482","label":"CPP — art. 482","paragraphs":["Art. 482. O Conselho de Sentença será questionado sobre matéria de fato e se o acusado deve ser absolvido. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Os quesitos serão redigidos em proposições afirmativas, simples e distintas, de modo que cada um deles possa ser respondido com suficiente clareza e necessária precisão. Na sua elaboração, o presidente levará em conta os termos da pronúncia ou das decisões posteriores que julgaram admissível a acusação, do interrogatório e das alegações das partes. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:483","law":"cpp","ref":"483","label":"CPP — art. 483","paragraphs":["Art. 483. Os quesitos serão formulados na seguinte ordem, indagando sobre: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - a materialidade do fato; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - a autoria ou participação; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","III - se o acusado deve ser absolvido; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação) (Vide ADPF nº 779/2021)","IV - se existe causa de diminuição de pena alegada pela defesa; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","V - se existe circunstância qualificadora ou causa de aumento de pena reconhecidas na pronúncia ou em decisões posteriores que julgaram admissível a acusação. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º A resposta negativa, de mais de 3 (três) jurados, a qualquer dos quesitos referidos nos incisos I e II do caput deste artigo encerra a votação e implica a absolvição do acusado. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Respondidos afirmativamente por mais de 3 (três) jurados os quesitos relativos aos incisos I e II do caput deste artigo será formulado quesito com a seguinte redação:","O jurado absolve o acusado? (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação) (Vide ADPF nº 779/2021)","§ 3º Decidindo os jurados pela condenação, o julgamento prossegue, devendo ser formulados quesitos sobre:","I - causa de diminuição de pena alegada pela defesa;","II - circunstância qualificadora ou causa de aumento de pena, reconhecidas na pronúncia ou em decisões posteriores que julgaram admissível a acusação. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 4º Sustentada a desclassificação da infração para outra de competência do juiz singular, será formulado quesito a respeito, para ser respondido após o 2º (segundo) ou 3º (terceiro) quesito, conforme o caso. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 5º Sustentada a tese de ocorrência do crime na sua forma tentada ou havendo divergência sobre a tipificação do delito, sendo este da competência do Tribunal do Júri, o juiz formulará quesito acerca destas questões, para ser respondido após o segundo quesito. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 6º Havendo mais de um crime ou mais de um acusado, os quesitos serão formulados em séries distintas. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:484","law":"cpp","ref":"484","label":"CPP — art. 484","paragraphs":["Art. 484. A seguir, o presidente lerá os quesitos e indagará das partes se têm requerimento ou reclamação a fazer, devendo qualquer deles, bem como a decisão, constar da ata.","Parágrafo único. Ainda em plenário, o juiz presidente explicará aos jurados o significado de cada quesito. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:485","law":"cpp","ref":"485","label":"CPP — art. 485","paragraphs":["Art. 485. Não havendo dúvida a ser esclarecida, o juiz presidente, os jurados, o Ministério Público, o assistente, o querelante, o defensor do acusado, o escrivão e o oficial de justiça dirigir-se-ão à sala especial a fim de ser procedida a votação. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Na falta de sala especial, o juiz presidente determinará que o público se retire, permanecendo somente as pessoas mencionadas no caput deste artigo. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º O juiz presidente advertirá as partes de que não será permitida qualquer intervenção que possa perturbar a livre manifestação do Conselho e fará retirar da sala quem se portar inconvenientemente. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:486","law":"cpp","ref":"486","label":"CPP — art. 486","paragraphs":["Art. 486. Antes de proceder-se à votação de cada quesito, o juiz presidente mandará distribuir aos jurados pequenas cédulas, feitas de papel opaco e facilmente dobráveis, contendo 7 (sete) delas a palavra sim, 7 (sete) a palavra não. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:487","law":"cpp","ref":"487","label":"CPP — art. 487","paragraphs":["Art. 487. Para assegurar o sigilo do voto, o oficial de justiça recolherá em urnas separadas as cédulas correspondentes aos votos e as não utilizadas. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:488","law":"cpp","ref":"488","label":"CPP — art. 488","paragraphs":["Art. 488. Após a resposta, verificados os votos e as cédulas não utilizadas, o presidente determinará que o escrivão registre no termo a votação de cada quesito, bem como o resultado do julgamento. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Do termo também constará a conferência das cédulas não utilizadas. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:489","law":"cpp","ref":"489","label":"CPP — art. 489","paragraphs":["Art. 489. As decisões do Tribunal do Júri serão tomadas por maioria de votos. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:490","law":"cpp","ref":"490","label":"CPP — art. 490","paragraphs":["Art. 490. Se a resposta a qualquer dos quesitos estiver em contradição com outra ou outras já dadas, o presidente, explicando aos jurados em que consiste a contradição, submeterá novamente à votação os quesitos a que se referirem tais respostas. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Se, pela resposta dada a um dos quesitos, o presidente verificar que ficam prejudicados os seguintes, assim o declarará, dando por finda a votação. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:593","law":"cpp","ref":"593","label":"CPP — art. 593","paragraphs":["Art. 593. Caberá apelação no prazo de cinco dias: (“Caput” do artigo com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","I - das sentenças definitivas de condenação ou absolvição proferidas por Juiz singular; (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","II - das decisões definitivas, ou com força de definitivas, proferidas por Juiz singular, nos casos não previstos no capítulo anterior; (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","III - das decisões do Tribunal do Júri, quando: (Inciso com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","a) ocorrer nulidade posterior à pronúncia; (Alínea com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","b) for a sentença do Juiz Presidente contrária à lei expressa ou à decisão dos jurados; (Alínea com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","c) houver erro ou injustiça no tocante à aplicação da pena ou da medida de segurança; (Alínea com redação dada pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","d) for a decisão dos jurados manifestamente contrária à prova dos autos. (Alínea acrescida pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 1º Se a sentença do Juiz Presidente for contrária à lei expressa ou divergir das respostas dos jurados aos quesitos, o Tribunal ad quem fará a devida retificação. (Parágrafo acrescido pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 2º Interposta a apelação com fundamento no nº III, letra c , deste artigo, o Tribunal ad quem, se lhe der provimento retificará a aplicação da pena ou da medida de segurança. (Parágrafo acrescido pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 3º Se a apelação se fundar no nº III, letra d, deste artigo, e o Tribunal ad quem se convencer de que a decisão dos jurados é manifestamente contrária à prova dos autos, dar-lhe-á provimento para sujeitar o réu a novo julgamento; não se admite, porém, pelo mesmo motivo, segunda apelação.","(Parágrafo acrescido pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)","§ 4º Quando cabível a apelação, não poderá ser usado o recurso em sentido estrito, ainda que somente de parte da decisão se recorra. (Parágrafo único transformado em § 4º pela Lei nº 263, de 23/2/1948, publicada no DOU de 26/2/1948, em vigor: no Distrito Federal, 3 dias após a publicação; 10 dias nos Estados do Rio de Janeiro, São Paulo e Minas; e, 20 dias, nos demais Estados e Territórios)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:492","law":"cpp","ref":"492","label":"CPP — art. 492","paragraphs":["Art. 492. Em seguida, o presidente proferirá sentença que: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - no caso de condenação: (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","a) fixará a pena-base; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","b) considerará as circunstâncias agravantes ou atenuantes alegadas nos debates; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","c) imporá os aumentos ou diminuições da pena, em atenção às causas admitidas pelo júri; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","d) observará as demais disposições do art. 387 deste Código; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","e) mandará o acusado recolher-se ou recomendá-lo-á à prisão em que se encontra, se presentes os requisitos da prisão preventiva, ou, no caso de condenação a uma pena igual ou superior a 15 (quinze) anos de reclusão, determinará a execução provisória das penas, com expedição do mandado de prisão, se for o caso, sem prejuízo do conhecimento de recursos que vierem a ser interpostos; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, e com nova redação dada pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","f) estabelecerá os efeitos genéricos e específicos da condenação; (Alínea acrescida pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - no caso de absolvição:","a) mandará colocar em liberdade o acusado se por outro motivo não estiver preso;","b) revogará as medidas restritivas provisoriamente decretadas;","c) imporá, se for o caso, a medida de segurança cabível. (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Se houver desclassificação da infração para outra, de competência do juiz singular, ao presidente do Tribunal do Júri caberá proferir sentença em seguida, aplicando-se, quando o delito resultante da nova tipificação for considerado pela lei como infração penal de menor potencial ofensivo, o disposto nos arts. 69 e seguintes da Lei nº 9.099, de 26 de setembro de 1995. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Em caso de desclassificação, o crime conexo que não seja doloso contra a vida será julgado pelo juiz presidente do Tribunal do Júri, aplicando-se, no que couber, o disposto no § 1º deste artigo. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º O presidente poderá, excepcionalmente, deixar de autorizar a execução provisória das penas de que trata a alínea e do inciso I do caput deste artigo, se houver questão substancial cuja resolução pelo tribunal ao qual competir o julgamento possa plausivelmente levar à revisão da condenação. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 4º A apelação interposta contra decisão condenatória do Tribunal do Júri a uma pena igual ou superior a 15 (quinze) anos de reclusão não terá efeito suspensivo. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 5º Excepcionalmente, poderá o tribunal atribuir efeito suspensivo à apelação de que trata o § 4º deste artigo, quando verificado cumulativamente que o recurso:","I - não tem propósito meramente protelatório; e","II - levanta questão substancial e que pode resultar em absolvição, anulação da sentença, novo julgamento ou redução da pena para patamar inferior a 15 (quinze) anos de reclusão. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)","§ 6º O pedido de concessão de efeito suspensivo poderá ser feito incidentemente na apelação ou por meio de petição em separado dirigida diretamente ao relator, instruída com cópias da sentença condenatória, das razões da apelação e de prova da tempestividade, das contrarrazões e das demais peças necessárias à compreensão da controvérsia. (Parágrafo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"l15358:2","law":"l15358","ref":"2","label":"Lei 15358 — art. 2","paragraphs":["Art. 2º Constitui crime, independentemente de suas razões ou motivações, a prática, por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, nos termos do § 2º deste artigo, de qualquer das seguintes condutas:","I - utilizar violência ou grave ameaça para intimidar, coagir ou constranger a população ou agentes públicos, com o propósito de impor ou exercer o controle, o domínio ou a influência, total ou parcial, sobre áreas geográficas, comunidades ou territórios;","II - empregar ou ameaçar por meio da utilização de armas de fogo, explosivos, gases tóxicos, venenos, agentes biológicos, químicos ou nucleares, expondo a perigo a paz e a incolumidade pública;","III - impedir, dificultar, obstruir ou criar embaraços à atuação das forças de segurança pública, à perseguição policial ou às operações de manutenção da ordem, mediante a colocação de barricadas, bloqueios, obstáculos físicos, incêndios, destruição de vias, uso de artefatos ou qualquer outro meio destinado a restringir o deslocamento, a visibilidade ou a ação policial;","IV - impor, mediante violência ou grave ameaça, qualquer tipo de controle social para o exercício de atividade econômica, comercial, de serviços públicos ou comunitários;","V - usar explosivos, armas de fogo ou equipamentos para prática de crimes contra instituições financeiras de qualquer natureza, base de valores ou carros-fortes ou para interromper, total ou parcialmente, fluxo terrestre, aéreo ou aquaviário, com o objetivo de obstruir, dificultar ou postergar a atuação preventiva ou repressiva do Estado;","VI - promover ataques, com violência ou grave ameaça, contra instituições prisionais;","VII - apoderar-se ilicitamente de meios de transporte ou danificá-los, depredá-los, incendiá-los, destruí-los, saqueá-los, explodi-los ou inutilizá-los, total ou parcialmente;","VIII - apoderar-se ilicitamente de aeronaves ou sabotá-las, expondo a perigo a vida ou a integridade física de uma ou mais pessoas ou comprometendo a segurança da aviação civil;","IX - apoderar-se do funcionamento, sabotá-lo ou inutilizá-lo, total ou parcialmente, ainda que de modo temporário, de portos, aeroportos, estações e linhas férreas ou rodoviárias, hospitais, casas de saúde, escolas, estádios esportivos, instalações públicas ou locais onde funcionem serviços públicos essenciais, instalações de geração, transmissão ou distribuição de energia, unidades militares ou instalações de exploração, refino e processamento de petróleo e gás;","X - interromper, danificar, perturbar ou dificultar o restabelecimento dos bancos de dados públicos, bem como dos serviços informático, telegráfico, radiotelegráfico, telefônico ou telemático governamentais ou de interesse coletivo, com o fim de desorientar o funcionamento, subtrair informações sigilosas ou obter vantagem de qualquer natureza.","Pena - reclusão, de 20 (vinte) a 40 (quarenta) anos, sem prejuízo das sanções correspondentes à ameaça, à violência ou a de outros crimes previstos na legislação penal.","§ 1º Aumenta-se a pena de 2/3 (dois terços) ao dobro se:","I - o agente exercer comando ou liderança, individual ou coletiva, da organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, mesmo que não tenha praticado pessoalmente os atos materiais de execução;","II - o agente, de qualquer forma, prover ou levantar fundos, bens, direitos, valores, serviços ou informações para o financiamento, total ou parcial, das condutas previstas nos incisos I a X do caput deste artigo;","III - as condutas previstas nos incisos I a X do caput deste artigo forem praticadas com o emprego de violência ou grave ameaça contra membro do Poder Judiciário, membro do Ministério Público, agentes de segurança descritos no art.","144 da Constituição Federal ou policiais institucionais de órgãos públicos, criança, adolescente, pessoa idosa, pessoa com deficiência ou qualquer pessoa em situação de vulnerabilidade ou houver o envolvimento, a coação ou o aliciamento destes para a prática ou auxílio na prática dos atos;","IV - houver conexão com outras organizações criminosas ultraviolentas;","V - houver concurso de funcionário público, valendo-se a organização criminosa ultraviolenta dessa condição para a prática de infração penal;","VI - houver infiltração no setor público ou atuação direta ou indireta na administração de serviços públicos ou em contratos governamentais;","VII - houver emprego de arma de fogo de uso restrito ou proibido, explosivo ou artefato análogo que cause perigo comum;","VIII - o agente recrutar, atrair, convidar, induzir, coagir, permitir ou consentir que criança ou adolescente integre, auxilie, se associe, ainda que de forma eventual ou ocasional, ou execute atos previstos no caput deste artigo;","IX - as circunstâncias do fato evidenciarem a existência de relações transnacionais ou houver a destinação do produto ou proveito da infração penal, no todo ou em parte, ao exterior;","X - o crime for cometido com o fim de obter vantagem econômica com a extração ilegal de recursos minerais ou a exploração econômica não autorizada, sem prejuízo das sanções específicas previstas na legislação ambiental e penal, de florestas e demais formas de vegetação, de terras de domínio público ou devolutas ou de áreas de preservação permanente e de unidades de conservação;","XI - houver o emprego de drones, veículos aéreos não tripulados, sistemas de vigilância eletrônica sofisticados, equipamentos de contrainteligência, tecnologias de interferência comunicacional, programas de criptografia avançada ou quaisquer recursos tecnológicos de natureza similar para monitoramento territorial, inteligência operacional, comunicações cifradas, dissimulação de identidade, georreferenciamento de operações repressivas ou qualquer outro meio destinado a facilitar, a coordenar ou a defender a prática dos atos descritos neste artigo.","§ 2º Para os fins desta Lei, considera-se organização criminosa ultraviolenta, denominada facção criminosa, o agrupamento de 3 (três) ou mais pessoas que emprega violência, grave ameaça ou coação para impor controle territorial ou social, intimidar populações ou autoridades ou atacar serviços, infraestrutura ou equipamentos essenciais ou que pratica atos destinados à execução dos crimes tipificados nesta Lei.","§ 3º (VETADO).","§ 4º Os crimes previstos neste artigo são insuscetíveis de:","I - anistia, graça e indulto;","II - fiança;","III - livramento condicional.","§ 5º Aquele que praticar atos preparatórios, com propósito inequívoco de consumar qualquer das condutas tipificadas neste artigo, estará sujeito à pena do crime consumado, reduzida de 1/3 (um terço) até a 1/2 (metade).","§ 6º Fica vedada a concessão do benefício de auxílio-reclusão, previsto no art. 80 da Lei nº 8.213, de 24 de julho de 1991, aos dependentes do segurado que estiver preso cautelarmente ou cumprindo pena privativa de liberdade em regime fechado ou semiaberto, em razão do cometimento dos crimes previstos neste artigo.","§ 7º As pessoas condenadas ou cautelarmente custodiadas pela prática das condutas previstas neste artigo, sempre que houver indícios concretos de que exerçam liderança ou chefia ou integrem núcleo de comando de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, cumprirão obrigatoriamente a pena ou a custódia em estabelecimento penal federal de segurança máxima, nos termos da Lei nº 11.671, de 8 de maio de 2008.","§ 8º Os homicídios cometidos por membros de organizações criminosas ultraviolentas, grupo paramilitar ou milícia privada, ou sua tentativa, quando conexos aos crimes a que se refere este artigo, serão julgados pelas Varas Criminais Colegiadas a que se refere o art. 1º-A da Lei nº 12.694, de 24 de julho de 2012.","§ 9º A prática dos crimes previstos neste artigo é causa suficiente para decretação de prisão preventiva."],"url":"https://www2.camara.leg.br/legin/fed/lei/2026/lei-15358-24-marco-2026-798846-publicacaooriginal-178585-pl.html"},{"key":"l12694:1-A","law":"l12694","ref":"1-A","label":"Lei 12694 — art. 1-A","paragraphs":["Art. 1º-A. Os Tribunais de Justiça e os Tribunais Regionais Federais poderão instalar, nas comarcas sedes de Circunscrição ou Seção Judiciária, mediante resolução, Varas Criminais Colegiadas com competência para o processo e julgamento:","I - de crimes de pertinência a organizações criminosas armadas ou que tenham armas à disposição;","II - do crime do art. 288-A do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal); e","III - das infrações penais conexas aos crimes a que se referem os incisos I e II do caput deste artigo.","§ 1º As Varas Criminais Colegiadas terão competência para todos os atos jurisdicionais no decorrer da investigação, da ação penal e da execução da pena, inclusive a transferência do preso para estabelecimento prisional de segurança máxima ou para regime disciplinar diferenciado.","§ 2º Ao receber, segundo as regras normais de distribuição, processos ou procedimentos que tenham por objeto os crimes mencionados no caput deste artigo, o juiz deverá declinar da competência e remeter os autos, em qualquer fase em que se encontrem, à Vara Criminal Colegiada de sua Circunscrição ou Seção Judiciária.","§ 3º Feita a remessa mencionada no § 2º deste artigo, a Vara Criminal Colegiada terá competência para todos os atos processuais posteriores, incluindo os da fase de execução. (Artigo acrescido pela Lei nº 13.964, de 24/12/2019, publicada na Edição Extra do DOU de 24/12/2019, em vigor 30 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/lei/2012/lei-12694-24-julho-2012-773906-normaatualizada-pl.html"},{"key":"cpp:417","law":"cpp","ref":"417","label":"CPP — art. 417","paragraphs":["Art. 417. Se houver indícios de autoria ou de participação de outras pessoas não incluídas na acusação, o juiz, ao pronunciar ou impronunciar o acusado, determinará o retorno dos autos ao Ministério Público, por 15 (quinze) dias, aplicável, no que couber, o art. 80 deste Código. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:420","law":"cpp","ref":"420","label":"CPP — art. 420","paragraphs":["Art. 420. A intimação da decisão de pronúncia será feita: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - pessoalmente ao acusado, ao defensor nomeado e ao Ministério Público; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - ao defensor constituído, ao querelante e ao assistente do Ministério Público, na forma do disposto no § 1º do art. 370 deste Código. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Será intimado por edital o acusado solto que não for encontrado. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:424","law":"cpp","ref":"424","label":"CPP — art. 424","paragraphs":["Art. 424. Quando a lei local de organização judiciária não atribuir ao presidente do Tribunal do Júri o preparo para julgamento, o juiz competente remeter-lhe-á os autos do processo preparado até 5 (cinco) dias antes do sorteio a que se refere o art. 433 deste Código.","Parágrafo único. Deverão ser remetidos, também, os processos preparados até o encerramento da reunião, para a realização de julgamento. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:425","law":"cpp","ref":"425","label":"CPP — art. 425","paragraphs":["Art. 425. Anualmente, serão alistados pelo presidente do Tribunal do Júri de 800 (oitocentos) a 1.500 (um mil e quinhentos) jurados nas comarcas de mais de 1.000.000 (um milhão) de habitantes, de 300 (trezentos) a 700 (setecentos) nas comarcas de mais de 100.000 (cem mil) habitantes e de 80 (oitenta) a 400 (quatrocentos) nas comarcas de menor população. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Nas comarcas onde for necessário, poderá ser aumentado o número de jurados e, ainda, organizada lista de suplentes, depositadas as cédulas em urna especial, com as cautelas mencionadas na parte final do § 3º do art. 426 deste Código. (Parágrafo único transformado em § 1º e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º O juiz presidente requisitará às autoridades locais, associações de classe e de bairro, entidades associativas e culturais, instituições de ensino em geral, universidades, sindicatos, repartições públicas e outros núcleos comunitários a indicação de pessoas que reúnam as condições para exercer a função de jurado. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:426","law":"cpp","ref":"426","label":"CPP — art. 426","paragraphs":["Art. 426. A lista geral dos jurados, com indicação das respectivas profissões, será publicada pela imprensa até o dia 10 de outubro de cada ano e divulgada em editais afixados à porta do Tribunal do Júri. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º A lista poderá ser alterada, de ofício ou mediante reclamação de qualquer do povo ao juiz presidente até o dia 10 de novembro, data de sua publicação definitiva. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Juntamente com a lista, serão transcritos os arts. 436 a 446 deste Código. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Os nomes e endereços dos alistados, em cartões iguais, após serem verificados na presença do Ministério Público, de advogado indicado pela Seção local da Ordem dos Advogados do Brasil e de defensor indicado pelas Defensorias Públicas competentes, permanecerão guardados em urna fechada a chave, sob a responsabilidade do juiz presidente. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 4º O jurado que tiver integrado o Conselho de Sentença nos 12 (doze) meses que antecederem à publicação da lista geral fica dela excluído. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 5º Anualmente, a lista geral de jurados será, obrigatoriamente, completada. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:429","law":"cpp","ref":"429","label":"CPP — art. 429","paragraphs":["Art. 429. Salvo motivo relevante que autorize alteração na ordem dos julgamentos, terão preferência: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - os acusados presos; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - dentre os acusados presos, aqueles que estiverem há mais tempo na prisão; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","III - em igualdade de condições, os precedentemente pronunciados. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Antes do dia designado para o primeiro julgamento da reunião periódica, será afixada na porta do edifício do Tribunal do Júri a lista dos processos a serem julgados, obedecida a ordem prevista no caput deste artigo. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º O juiz presidente reservará datas na mesma reunião periódica para a inclusão de processo que tiver o julgamento adiado. (Parágrafo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:430","law":"cpp","ref":"430","label":"CPP — art. 430","paragraphs":["Art. 430. O assistente somente será admitido se tiver requerido sua habilitação até 5 (cinco) dias antes da data da sessão na qual pretenda atuar. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:431","law":"cpp","ref":"431","label":"CPP — art. 431","paragraphs":["Art. 431. Estando o processo em ordem, o juiz presidente mandará intimar as partes, o ofendido, se for possível, as testemunhas e os peritos, quando houver requerimento, para a sessão de instrução e julgamento, observando, no que couber, o disposto no art. 420 deste Código. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:432","law":"cpp","ref":"432","label":"CPP — art. 432","paragraphs":["Art. 432. Em seguida à organização da pauta, o juiz presidente determinará a intimação do Ministério Público, da Ordem dos Advogados do Brasil e da Defensoria Pública para acompanharem, em dia e hora designados, o sorteio dos jurados que atuarão na reunião periódica. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:433","law":"cpp","ref":"433","label":"CPP — art. 433","paragraphs":["Art. 433. O sorteio, presidido pelo juiz, far-se-á a portas abertas, cabendo-lhe retirar as cédulas até completar o número de 25 (vinte e cinco) jurados, para a reunião periódica ou extraordinária. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º O sorteio será realizado entre o 15º (décimo quinto) e o 10º (décimo) dia útil antecedente à instalação da reunião. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º A audiência de sorteio não será adiada pelo não comparecimento das partes. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º O jurado não sorteado poderá ter o seu nome novamente incluído para as reuniões futuras. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:434","law":"cpp","ref":"434","label":"CPP — art. 434","paragraphs":["Art. 434. Os jurados sorteados serão convocados pelo correio ou por qualquer outro meio hábil para comparecer no dia e hora designados para a reunião, sob as penas da lei. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. No mesmo expediente de convocação serão transcritos os arts. 436 a 446 deste Código. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:435","law":"cpp","ref":"435","label":"CPP — art. 435","paragraphs":["Art. 435. Serão afixados na porta do edifício do Tribunal do Júri a relação dos jurados convocados, os nomes do acusado e dos procuradores das partes, além do dia, hora e local das sessões de instrução e julgamento. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:436","law":"cpp","ref":"436","label":"CPP — art. 436","paragraphs":["Art. 436. O serviço do júri é obrigatório. O alistamento compreenderá os cidadãos maiores de 18 (dezoito) anos de notória idoneidade. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Nenhum cidadão poderá ser excluído dos trabalhos do júri ou deixar de ser alistado em razão de cor ou etnia, raça, credo, sexo, profissão, classe social ou econômica, origem ou grau de instrução. (Parágrafo único transformado em § 1º e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º A recusa injustificada ao serviço do júri acarretará multa no valor de 1 (um) a 10 (dez) salários mínimos, a critério do juiz, de acordo com a condição econômica do jurado. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:437","law":"cpp","ref":"437","label":"CPP — art. 437","paragraphs":["Art. 437. Estão isentos do serviço do júri: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - o Presidente da República e os Ministros de Estado; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - os Governadores e seus respectivos Secretários; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","III - os membros do Congresso Nacional, das Assembléias Legislativas e das Câmaras Distrital e Municipais; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","IV - os Prefeitos Municipais; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","V - os Magistrados e membros do Ministério Público e da Defensoria Pública; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VI - os servidores do Poder Judiciário, do Ministério Público e da Defensoria Pública; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VII - as autoridades e os servidores da polícia e da segurança pública; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VIII - os militares em serviço ativo; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","IX - os cidadãos maiores de 70 (setenta) anos que requeiram sua dispensa; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","X - aqueles que o requererem, demonstrando justo impedimento. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:438","law":"cpp","ref":"438","label":"CPP — art. 438","paragraphs":["Art. 438. A recusa ao serviço do júri fundada em convicção religiosa, filosófica ou política importará no dever de prestar serviço alternativo, sob pena de suspensão dos direitos políticos, enquanto não prestar o serviço imposto. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Entende-se por serviço alternativo o exercício de atividades de caráter administrativo, assistencial, filantrópico ou mesmo produtivo, no Poder Judiciário, na Defensoria Pública, no Ministério Público ou em entidade conveniada para esses fins. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º O juiz fixará o serviço alternativo atendendo aos princípios da proporcionalidade e da razoabilidade. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:439","law":"cpp","ref":"439","label":"CPP — art. 439","paragraphs":["Art. 439. O exercício efetivo da função de jurado constituirá serviço público relevante e estabelecerá presunção de idoneidade moral. (Artigo com redação dada pela Lei nº 12.403, de 4/5/2011, publicada no DOU de 5/5/2011, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:440","law":"cpp","ref":"440","label":"CPP — art. 440","paragraphs":["Art. 440. Constitui também direito do jurado, na condição do art. 439 deste Código, preferência, em igualdade de condições, nas licitações públicas e no provimento, mediante concurso, de cargo ou função pública, bem como nos casos de promoção funcional ou remoção voluntária. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:441","law":"cpp","ref":"441","label":"CPP — art. 441","paragraphs":["Art. 441. Nenhum desconto será feito nos vencimentos ou salário do jurado sorteado que comparecer à sessão do júri. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:442","law":"cpp","ref":"442","label":"CPP — art. 442","paragraphs":["Art. 442. Ao jurado que, sem causa legítima, deixar de comparecer no dia marcado para a sessão ou retirar-se antes de ser dispensado pelo presidente será aplicada multa de 1 (um) a 10 (dez) salários mínimos, a critério do juiz, de acordo com a sua condição econômica. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:443","law":"cpp","ref":"443","label":"CPP — art. 443","paragraphs":["Art. 443. Somente será aceita escusa fundada em motivo relevante devidamente comprovado e apresentada, ressalvadas as hipóteses de força maior, até o momento da chamada dos jurados. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:444","law":"cpp","ref":"444","label":"CPP — art. 444","paragraphs":["Art. 444. O jurado somente será dispensado por decisão motivada do juiz presidente, consignada na ata dos trabalhos. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:445","law":"cpp","ref":"445","label":"CPP — art. 445","paragraphs":["Art. 445. O jurado, no exercício da função ou a pretexto de exercê-la, será responsável criminalmente nos mesmos termos em que o são os juízes togados. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:446","law":"cpp","ref":"446","label":"CPP — art. 446","paragraphs":["Art. 446. Aos suplentes, quando convocados, serão aplicáveis os dispositivos referentes às dispensas, faltas e escusas e à equiparação de responsabilidade penal prevista no art. 445 deste Código. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:447","law":"cpp","ref":"447","label":"CPP — art. 447","paragraphs":["Art. 447. O Tribunal do Júri é composto por 1 (um) juiz togado, seu presidente e por 25 (vinte e cinco) jurados que serão sorteados dentre os alistados, 7 (sete) dos quais constituirão o Conselho de Sentença em cada sessão de julgamento. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:448","law":"cpp","ref":"448","label":"CPP — art. 448","paragraphs":["Art. 448. São impedidos de servir no mesmo Conselho: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - marido e mulher; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - ascendente e descendente; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","III - sogro e genro ou nora; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","IV - irmãos e cunhados, durante o cunhadio; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","V - tio e sobrinho; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VI - padrasto, madrasta ou enteado. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º O mesmo impedimento ocorrerá em relação às pessoas que mantenham união estável reconhecida como entidade familiar. (Parágrafo único transformado em § 1º e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Aplicar-se-á aos jurados o disposto sobre os impedimentos, a suspeição e as incompatibilidades dos juízes togados. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:449","law":"cpp","ref":"449","label":"CPP — art. 449","paragraphs":["Art. 449. Não poderá servir o jurado que: (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","I - tiver funcionado em julgamento anterior do mesmo processo, independentemente da causa determinante do julgamento posterior; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - no caso do concurso de pessoas, houver integrado o Conselho de Sentença que julgou o outro acusado; (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","III - tiver manifestado prévia disposição para condenar ou absolver o acusado. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:450","law":"cpp","ref":"450","label":"CPP — art. 450","paragraphs":["Art. 450. Dos impedidos entre si por parentesco ou relação de convivência, servirá o que houver sido sorteado em primeiro lugar. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:451","law":"cpp","ref":"451","label":"CPP — art. 451","paragraphs":["Art. 451. Os jurados excluídos por impedimento, suspeição ou incompatibilidade serão considerados para a constituição do número legal exigível para a realização da sessão. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:452","law":"cpp","ref":"452","label":"CPP — art. 452","paragraphs":["Art. 452. O mesmo Conselho de Sentença poderá conhecer de mais de um processo, no mesmo dia, se as partes o aceitarem, hipótese em que seus integrantes deverão prestar novo compromisso. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:453","law":"cpp","ref":"453","label":"CPP — art. 453","paragraphs":["Art. 453. O Tribunal do Júri reunir-se-á para as sessões de instrução e julgamento nos períodos e na forma estabelecida pela lei local de organização judiciária. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:454","law":"cpp","ref":"454","label":"CPP — art. 454","paragraphs":["Art. 454. Até o momento de abertura dos trabalhos da sessão, o juiz presidente decidirá os casos de isenção e dispensa de jurados e o pedido de adiamento de julgamento, mandando consignar em ata as deliberações. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:455","law":"cpp","ref":"455","label":"CPP — art. 455","paragraphs":["Art. 455. Se o Ministério Público não comparecer, o juiz presidente adiará o julgamento para o primeiro dia desimpedido da mesma reunião, cientificadas as partes e as testemunhas. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. Se a ausência não for justificada, o fato será imediatamente comunicado ao Procurador-Geral de Justiça com a data designada para a nova sessão. (Primitivo § 1º transformado em parágrafo único e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:456","law":"cpp","ref":"456","label":"CPP — art. 456","paragraphs":["Art. 456. Se a falta, sem escusa legítima, for do advogado do acusado, e se outro não for por este constituído, o fato será imediatamente comunicado ao presidente da seccional da Ordem dos Advogados do Brasil, com a data designada para a nova sessão. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Não havendo escusa legítima, o julgamento será adiado somente uma vez, devendo o acusado ser julgado quando chamado novamente. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Na hipótese do § 1º deste artigo, o juiz intimará a Defensoria Pública para o novo julgamento, que será adiado para o primeiro dia desimpedido, observado o prazo mínimo de 10 (dez) dias. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:457","law":"cpp","ref":"457","label":"CPP — art. 457","paragraphs":["Art. 457. O julgamento não será adiado pelo não comparecimento do acusado solto, do assistente ou do advogado do querelante, que tiver sido regularmente intimado. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Os pedidos de adiamento e as justificações de não comparecimento deverão ser, salvo comprovado motivo de força maior, previamente submetidos à apreciação do juiz presidente do Tribunal do Júri. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Se o acusado preso não for conduzido, o julgamento será adiado para o primeiro dia desimpedido da mesma reunião, salvo se houver pedido de dispensa de comparecimento subscrito por ele e seu defensor. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:458","law":"cpp","ref":"458","label":"CPP — art. 458","paragraphs":["Art. 458. Se a testemunha, sem justa causa, deixar de comparecer, o juiz presidente, sem prejuízo da ação penal pela desobediência, aplicar-lhe-á a multa prevista no § 2º do art. 436 deste Código. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:459","law":"cpp","ref":"459","label":"CPP — art. 459","paragraphs":["Art. 459. Aplicar-se-á às testemunhas a serviço do Tribunal do Júri o disposto no art. 441 deste Código. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:460","law":"cpp","ref":"460","label":"CPP — art. 460","paragraphs":["Art. 460. Antes de constituído o Conselho de Sentença, as testemunhas serão recolhidas a lugar onde umas não possam ouvir os depoimentos das outras. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:461","law":"cpp","ref":"461","label":"CPP — art. 461","paragraphs":["Art. 461. O julgamento não será adiado se a testemunha deixar de comparecer, salvo se uma das partes tiver requerido a sua intimação por mandado, na oportunidade de que trata o art. 422 deste Código, declarando não prescindir do depoimento e indicando a sua localização. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Se, intimada, a testemunha não comparecer, o juiz presidente suspenderá os trabalhos e mandará conduzi-la ou adiará o julgamento para o primeiro dia desimpedido, ordenando a sua condução. (Parágrafo único transformado em § 1º e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º O julgamento será realizado mesmo na hipótese de a testemunha não ser encontrada no local indicado, se assim for certificado por oficial de justiça. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:462","law":"cpp","ref":"462","label":"CPP — art. 462","paragraphs":["Art. 462. Realizadas as diligências referidas nos arts. 454 a 461 deste Código, o juiz presidente verificará se a urna contém as cédulas dos 25 (vinte e cinco) jurados sorteados, mandando que o escrivão proceda à chamada deles. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:463","law":"cpp","ref":"463","label":"CPP — art. 463","paragraphs":["Art. 463. Comparecendo, pelo menos, 15 (quinze) jurados, o juiz presidente declarará instalados os trabalhos, anunciando o processo que será submetido a julgamento. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º O oficial de justiça fará o pregão, certificando a diligência nos autos. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Os jurados excluídos por impedimento ou suspeição serão computados para a constituição do número legal. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:464","law":"cpp","ref":"464","label":"CPP — art. 464","paragraphs":["Art. 464. Não havendo o número referido no art. 463 deste Código, proceder-se-á ao sorteio de tantos suplentes quantos necessários, e designar-se-á nova data para a sessão do júri. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:465","law":"cpp","ref":"465","label":"CPP — art. 465","paragraphs":["Art. 465. Os nomes dos suplentes serão consignados em ata, remetendo-se o expediente de convocação, com observância do disposto nos arts. 434 e 435 deste Código. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:467","law":"cpp","ref":"467","label":"CPP — art. 467","paragraphs":["Art. 467. Verificando que se encontram na urna as cédulas relativas aos jurados presentes, o juiz presidente sorteará 7 (sete) dentre eles para a formação do Conselho de Sentença. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:469","law":"cpp","ref":"469","label":"CPP — art. 469","paragraphs":["Art. 469. Se forem 2 (dois) ou mais os acusados, as recusas poderão ser feitas por um só defensor. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º A separação dos julgamentos somente ocorrerá se, em razão das recusas, não for obtido o número mínimo de 7 (sete) jurados para compor o Conselho de Sentença. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Determinada a separação dos julgamentos, será julgado em primeiro lugar o acusado a quem foi atribuída a autoria do fato ou, em caso de co-autoria, aplicar-se-á o critério de preferência disposto no art. 429 deste Código. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:470","law":"cpp","ref":"470","label":"CPP — art. 470","paragraphs":["Art. 470. Desacolhida a argüição de impedimento, de suspeição ou de incompatibilidade contra o juiz presidente do Tribunal do Júri, órgão do Ministério Público, jurado ou qualquer funcionário, o julgamento não será suspenso, devendo, entretanto, constar da ata o seu fundamento e a decisão. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:471","law":"cpp","ref":"471","label":"CPP — art. 471","paragraphs":["Art. 471. Se, em conseqüência do impedimento, suspeição, incompatibilidade, dispensa ou recusa, não houver número para a formação do Conselho, o julgamento será adiado para o primeiro dia desimpedido, após sorteados os suplentes, com observância do disposto no art. 464 deste Código. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:475","law":"cpp","ref":"475","label":"CPP — art. 475","paragraphs":["Art. 475. O registro dos depoimentos e do interrogatório será feito pelos meios ou recursos de gravação magnética, eletrônica, estenotipia ou técnica similar, destinada a obter maior fidelidade e celeridade na colheita da prova. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","Parágrafo único. A transcrição do registro, após feita a degravação, constará dos autos. (Parágrafo único acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:476","law":"cpp","ref":"476","label":"CPP — art. 476","paragraphs":["Art. 476. Encerrada a instrução, será concedida a palavra ao Ministério Público, que fará a acusação, nos limites da pronúncia ou das decisões posteriores que julgaram admissível a acusação, sustentando, se for o caso, a existência de circunstância agravante. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º O assistente falará depois do Ministério Público. (Parágrafo único transformado em § 1º e com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Tratando-se de ação penal de iniciativa privada, falará em primeiro lugar o querelante e, em seguida, o Ministério Público, salvo se este houver retomado a titularidade da ação, na forma do art. 29 deste Código. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Finda a acusação, terá a palavra a defesa. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 4º A acusação poderá replicar e a defesa treplicar, sendo admitida a reinquirição de testemunha já ouvida em plenário. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:480","law":"cpp","ref":"480","label":"CPP — art. 480","paragraphs":["Art. 480. A acusação, a defesa e os jurados poderão, a qualquer momento e por intermédio do juiz presidente, pedir ao orador que indique a folha dos autos onde se encontra a peça por ele lida ou citada, facultando-se, ainda, aos jurados solicitar-lhe, pelo mesmo meio, o esclarecimento de fato por ele alegado. (“Caput” do artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 1º Concluídos os debates, o presidente indagará dos jurados se estão habilitados a julgar ou se necessitam de outros esclarecimentos. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 2º Se houver dúvida sobre questão de fato, o presidente prestará esclarecimentos à vista dos autos. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","§ 3º Os jurados, nesta fase do procedimento, terão acesso aos autos e aos instrumentos do crime se solicitarem ao juiz presidente. (Parágrafo acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:481","law":"cpp","ref":"481","label":"CPP — art. 481","paragraphs":["Art. 481. Se a verificação de qualquer fato, reconhecida como essencial para o julgamento da causa, não puder ser realizada imediatamente, o juiz presidente dissolverá o Conselho, ordenando a realização das diligências entendidas necessárias.","Parágrafo único. Se a diligência consistir na produção de prova pericial, o juiz presidente, desde logo, nomeará perito e formulará quesitos, facultando às partes também formulá-los e indicar assistentes técnicos, no prazo de 5 (cinco) dias. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:491","law":"cpp","ref":"491","label":"CPP — art. 491","paragraphs":["Art. 491. Encerrada a votação, será o termo a que se refere o art. 488 deste Código assinado pelo presidente, pelos jurados e pelas partes. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:493","law":"cpp","ref":"493","label":"CPP — art. 493","paragraphs":["Art. 493. A sentença será lida em plenário pelo presidente antes de encerrada a sessão de instrução e julgamento. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:494","law":"cpp","ref":"494","label":"CPP — art. 494","paragraphs":["Art. 494. De cada sessão de julgamento o escrivão lavrará ata, assinada pelo presidente e pelas partes. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:495","law":"cpp","ref":"495","label":"CPP — art. 495","paragraphs":["Art. 495. A ata descreverá fielmente todas as ocorrências, mencionando obrigatoriamente:","I - a data e a hora da instalação dos trabalhos;","II - o magistrado que presidiu a sessão e os jurados presentes;","III - os jurados que deixaram de comparecer, com escusa ou sem ela, e as sanções aplicadas;","IV - o ofício ou requerimento de isenção ou dispensa;","V - o sorteio dos jurados suplentes;","VI - o adiamento da sessão, se houver ocorrido, com a indicação do motivo;","VII - a abertura da sessão e a presença do Ministério Público, do querelante e do assistente, se houver, e a do defensor do acusado;","VIII - o pregão e a sanção imposta, no caso de não comparecimento;","IX - as testemunhas dispensadas de depor;","X - o recolhimento das testemunhas a lugar de onde umas não pudessem ouvir o depoimento das outras;","XI - a verificação das cédulas pelo juiz presidente;","XII - a formação do Conselho de Sentença, com o registro dos nomes dos jurados sorteados e recusas;","XIII - o compromisso e o interrogatório, com simples referência ao termo;","XIV - os debates e as alegações das partes com os respectivos fundamentos;","XV - os incidentes;","XVI - o julgamento da causa;","XVII - a publicidade dos atos da instrução plenária, das diligências e da sentença. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:496","law":"cpp","ref":"496","label":"CPP — art. 496","paragraphs":["Art. 496. A falta da ata sujeitará o responsável a sanções administrativa e penal. (Artigo com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"},{"key":"cpp:497","law":"cpp","ref":"497","label":"CPP — art. 497","paragraphs":["Art. 497. São atribuições do juiz presidente do Tribunal do Júri, além de outras expressamente referidas neste Código:","I - regular a polícia das sessões e prender os desobedientes; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","II - requisitar o auxílio da força pública, que ficará sob sua exclusiva autoridade; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","III - dirigir os debates, intervindo em caso de abuso, excesso de linguagem ou mediante requerimento de uma das partes; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","IV - resolver as questões incidentes que não dependam de pronunciamento do júri; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","V - nomear defensor ao acusado, quando considerá-lo indefeso, podendo, neste caso, dissolver o Conselho e designar novo dia para o julgamento, com a nomeação ou a constituição de novo defensor; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VI - mandar retirar da sala o acusado que dificultar a realização do julgamento, o qual prosseguirá sem a sua presença; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VII - suspender a sessão pelo tempo indispensável à realização das diligências requeridas ou entendidas necessárias, mantida a incomunicabilidade dos jurados; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","VIII - interromper a sessão por tempo razoável, para proferir sentença e para repouso ou refeição dos jurados; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","IX - decidir, de ofício, ouvidos o Ministério Público e a defesa, ou a requerimento de qualquer destes, a argüição de extinção de punibilidade; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","X - resolver as questões de direito suscitadas no curso do julgamento; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","XI - determinar, de ofício ou a requerimento das partes ou de qualquer jurado, as diligências destinadas a sanar nulidade ou a suprir falta que prejudique o esclarecimento da verdade; (Inciso com redação dada pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)","XII - regulamentar, durante os debates, a intervenção de uma das partes, quando a outra estiver com a palavra, podendo conceder até 3 (três) minutos para cada aparte requerido, que serão acrescidos ao tempo desta última. (Inciso acrescido pela Lei nº 11.689, de 9/6/2008, publicada no DOU de 10/6/2008, em vigor 60 dias após a publicação)"],"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html"}];})(window);
